export const APP101 = "// app.mjs — LabFlow \"production\" thu nhỏ cho bài 10.1: một tiến trình Node phục vụ MỌI người dùng.\n//   node --inspect=127.0.0.1:49229 c101/app.mjs      (cổng app 41010)\nimport express from 'express';\n\nconst app = express();\nconst datLich = new Map([[7, { id: 7, phong: 'Lab 401', sv: 'SE1801-07', trangThai: 'CHO_DUYET' }]]);\n\napp.get('/health', (req, res) =&gt; res.json({ ok: true }));\n\napp.get('/dat-lich/:id', (req, res) =&gt; {\n  const id = Number(req.params.id);\n  const d = datLich.get(id); // BP — dòng bạn muốn \"xem thử một chút\" trên production\n  if (!d) return res.status(404).json({ loi: 'không có' });\n  res.json(d);\n});\n\napp.listen(41010, '127.0.0.1', () =&gt; console.log('app nghe 127.0.0.1:41010, pid', process.pid));";
export const TREO_NODE = "// treo-node.mjs — đặt một breakpoint (hoặc logpoint) vào tiến trình đang phục vụ, rồi đo người dùng KHÁC chờ bao lâu.\n//   node c101/treo-node.mjs bp|logpoint\n// Chỉ nối vào inspector 127.0.0.1:49229 của app.mjs do chính lab này chạy.\nimport fs from 'node:fs';\n\nconst CHE_DO = process.argv[2] || 'bp';\nconst APP = 'http://127.0.0.1:41010';\nconst nguon = fs.readFileSync(new URL('./app.mjs', import.meta.url), 'utf8').split('\\n');\nconst DONG = nguon.findIndex((x) =&gt; x.includes('// BP')); // 0-based, đúng kiểu CDP\n\nconst [muc] = await (await fetch('http://127.0.0.1:49229/json/list')).json();\nconst ws = new WebSocket(muc.webSocketDebuggerUrl);\nawait new Promise((r) =&gt; ws.addEventListener('open', r));\nlet so = 0; const cho = new Map(); const suKien = [];\nws.addEventListener('message', (e) =&gt; {\n  const m = JSON.parse(e.data);\n  if (m.id &amp;&amp; cho.has(m.id)) { cho.get(m.id)(m.result ?? m.error); cho.delete(m.id); }\n  else if (m.method) suKien.push(m);\n});\nconst goi = (method, params = {}) =&gt; new Promise((r) =&gt; { const id = ++so; cho.set(id, r); ws.send(JSON.stringify({ id, method, params })); });\n\nawait goi('Debugger.enable');\nconst dieuKien = CHE_DO === 'logpoint' ? 'console.log(\"[logpoint] id =\", id), false' : '';\nconst bp = await goi('Debugger.setBreakpointByUrl', { urlRegex: 'c101/app\\\\.mjs$', lineNumber: DONG, condition: dieuKien });\nconsole.log(`[${CHE_DO}] đặt tại app.mjs:${DONG + 1} — khớp ${bp.locations.length} vị trí`);\n\nconst t0 = Date.now();\nconst ms = () =&gt; String(Date.now() - t0).padStart(5) + ' ms';\nconst goiHttp = async (ten, duong) =&gt; {\n  const t = Date.now();\n  try {\n    const r = await fetch(APP + duong, { signal: AbortSignal.timeout(3000) });\n    return `${ten.padEnd(26)} ${duong.padEnd(12)} ${r.status}  sau ${Date.now() - t} ms`;\n  } catch (e) {\n    return `${ten.padEnd(26)} ${duong.padEnd(12)} ---  BỎ CUỘC sau ${Date.now() - t} ms (${e.name})`;\n  }\n};\n\n// 1) \"Bạn\" gọi đúng request cần soi\nconst cuaBan = goiHttp('bạn (người đang debug)', '/dat-lich/7');\nawait new Promise((r) =&gt; setTimeout(r, 300));\nconst dung = suKien.find((m) =&gt; m.method === 'Debugger.paused');\nconsole.log(`${ms()}  tiến trình ${dung ? 'ĐANG DỪNG ở breakpoint (Debugger.paused)' : 'vẫn chạy (không dừng)'}`);\n\n// 2) Trong lúc đó 8 người dùng khác bấm vào hệ thống\nconst khac = Array.from({ length: 8 }, (_, i) =&gt; goiHttp(`người dùng khác #${i + 1}`, i % 2 ? '/health' : '/dat-lich/7'));\n// 3) Bạn \"xem biến một chút\" mất 5 giây rồi mới bấm Continue\nawait new Promise((r) =&gt; setTimeout(r, 5000));\nif (dung) {\n  await goi('Debugger.resume'); console.log(`${ms()}  bạn bấm Continue`);\n  // breakpoint vẫn còn: request kế tiếp đang xếp hàng (của NGƯỜI KHÁC) chạm đúng dòng đó\n  for (let lan = 2; lan &lt;= 6; lan++) {\n    await new Promise((r) =&gt; setTimeout(r, 200));\n    const n = suKien.filter((m) =&gt; m.method === 'Debugger.paused').length;\n    if (n &lt; lan) break;\n    console.log(`${ms()}  DỪNG lần ${lan} — lần này là request của người dùng khác; bạn lại bấm Continue`);\n    await goi('Debugger.resume');\n  }\n}\nfor (const dong of await Promise.all([cuaBan, ...khac])) console.log('  ' + dong);\nawait goi('Debugger.removeBreakpoint', { breakpointId: bp.breakpointId });\nws.close();";
export const TREO_JAVA = "// Treo.java — debugger tí hon trên JDI (cùng API mà debugger IntelliJ dùng): đặt breakpoint, giữ 5 giây, rồi Resume.\n//   java tools/Treo.java &lt;cổng JDWP&gt; &lt;Lớp&gt; &lt;dòng&gt; all|thread\nimport com.sun.jdi.*;\nimport com.sun.jdi.connect.*;\nimport com.sun.jdi.event.*;\nimport com.sun.jdi.request.*;\nimport java.util.Map;\n\npublic class Treo {\n  public static void main(String[] a) throws Exception {\n    AttachingConnector c = Bootstrap.virtualMachineManager().attachingConnectors().stream()\n        .filter(x -&gt; x.transport().name().equals(\"dt_socket\")).findFirst().orElseThrow();\n    Map&lt;String, Connector.Argument&gt; args = c.defaultArguments();\n    args.get(\"hostname\").setValue(\"127.0.0.1\"); args.get(\"port\").setValue(a[0]);\n    VirtualMachine vm = c.attach(args);\n    Location loc = vm.classesByName(a[1]).get(0).locationsOfLine(Integer.parseInt(a[2])).get(0);\n    BreakpointRequest bp = vm.eventRequestManager().createBreakpointRequest(loc);\n    // IntelliJ: chuột phải vào chấm đỏ ⇒ Suspend: (•) All  ( ) Thread  — mặc định là All\n    bp.setSuspendPolicy(a[3].equals(\"all\") ? EventRequest.SUSPEND_ALL : EventRequest.SUSPEND_EVENT_THREAD);\n    bp.enable();\n    System.out.println(\"[\" + a[3] + \"] breakpoint tại \" + loc);\n    for (EventSet es = vm.eventQueue().remove(); ; es = vm.eventQueue().remove()) {\n      for (Event e : es) if (e instanceof BreakpointEvent be) {\n        long dung = vm.allThreads().stream().filter(ThreadReference::isSuspended).count();\n        System.out.println(\"DỪNG ở luồng \" + be.thread().name() + \" — số luồng JVM đang bị treo: \" + dung + \"/\" + vm.allThreads().size());\n        Thread.sleep(5000);\n        bp.disable();\n        es.resume();\n        System.out.println(\"Resume sau 5 s\");\n        vm.dispose();\n        return;\n      }\n      es.resume();\n    }\n  }\n}";
export const SEED = "-- seed.sql — bảng dat_lich của LabFlow (2.000 dòng, tất định) + vai trò chỉ đọc cho người trực.\nCREATE TABLE dat_lich (\n  id serial PRIMARY KEY,\n  phong_id int NOT NULL,\n  ngay date NOT NULL,\n  sinh_vien text NOT NULL,\n  trang_thai text NOT NULL DEFAULT 'DA_DUYET'\n);\nINSERT INTO dat_lich (phong_id, ngay, sinh_vien, trang_thai)\nSELECT 1 + (i * 7) % 20, DATE '2026-11-20' + ((i / 20) % 10), 'SE18' || lpad((i % 97)::text, 2, '0'),\n       CASE WHEN i % 5 = 0 THEN 'CHO_DUYET' ELSE 'DA_DUYET' END\nFROM generate_series(1, 2000) AS i;\n\n-- người trực chỉ cần ĐỌC: vai trò có sẵn pg_read_all_data (PostgreSQL 14+)\nCREATE ROLE truc_doc LOGIN PASSWORD 'truc-doc-lab';\nGRANT pg_read_all_data TO truc_doc;\nALTER ROLE truc_doc SET default_transaction_read_only = on;\nALTER ROLE truc_doc SET statement_timeout = '5s';";
export const DOC_SQL = "-- doc.sql — phiên của người trực bằng vai trò truc_doc: đọc được, không ghi được.\nSELECT current_user, current_setting('default_transaction_read_only') AS chi_doc;\nSELECT trang_thai, count(*) FROM dat_lich WHERE phong_id = 3 GROUP BY 1;\nUPDATE dat_lich SET trang_thai = 'HUY' WHERE id = 1;\nBEGIN READ WRITE;\nUPDATE dat_lich SET trang_thai = 'HUY' WHERE id = 1;\nROLLBACK;";
export const SUA_SQL = "-- sua.sql — ticket LAB-1042: \"Phòng 3 bảo trì ngày 25 và 26/11, huỷ mọi lượt đặt hai ngày đó\".\n-- Quy trình: giao dịch mở tay → đếm bằng đúng WHERE → so với con số mong đợi → sao lưu → sửa → kiểm → COMMIT.\nSET application_name = 'LAB-1042 cuong';\nBEGIN;\n-- (1) đếm trước. Ticket và trang quản trị nói: 20 lượt (10 mỗi ngày).\nSELECT count(*) FROM dat_lich WHERE phong_id = 3 AND ngay = '2026-11-25' OR ngay = '2026-11-26';\n-- 210 ≠ 20 ⇒ DỪNG. Người vội bỏ qua bước (1) sẽ chạy thẳng câu này:\nUPDATE dat_lich SET trang_thai = 'HUY' WHERE phong_id = 3 AND ngay = '2026-11-25' OR ngay = '2026-11-26';\nSELECT phong_id, count(*) FROM dat_lich WHERE trang_thai = 'HUY' GROUP BY 1 ORDER BY 2 DESC LIMIT 4;\nROLLBACK;\n-- (2) AND đứng trước OR. Viết lại bằng IN, đếm lại:\nBEGIN;\nSELECT count(*) FROM dat_lich WHERE phong_id = 3 AND ngay IN ('2026-11-25', '2026-11-26');\n-- (3) sao lưu đúng những dòng sắp đổi (để khôi phục được mà không cần restore cả DB)\nCREATE TABLE sao_luu_lab1042 AS SELECT * FROM dat_lich WHERE phong_id = 3 AND ngay IN ('2026-11-25', '2026-11-26');\n-- (4) sửa, RETURNING để thấy chính xác đã đổi gì\nUPDATE dat_lich SET trang_thai = 'HUY' WHERE phong_id = 3 AND ngay IN ('2026-11-25', '2026-11-26') RETURNING id, ngay, sinh_vien;\n-- (5) kiểm: đúng 20 dòng HUY, mọi dòng HUY đều là phòng 3\nSELECT count(*) AS huy, count(*) FILTER (WHERE phong_id &lt;&gt; 3) AS sai_phong FROM dat_lich WHERE trang_thai = 'HUY';\nCOMMIT;";
export const BC_APP = "// app.mjs — dịch vụ \"xuất báo cáo\" bị kẹt: request treo dần vì hàng đợi trong bộ nhớ không bao giờ chạy.\nimport http from 'node:http';\nconst hangDoi = [];            // việc đang chờ — chỉ sống trong bộ nhớ tiến trình\nlet dangChay = false;          // cờ \"đang có worker\" — lỗi: bị kẹt ở true sau một lần lỗi\nconst log = (o) =&gt; console.log(JSON.stringify({ t: new Date().toISOString(), ...o }));\nasync function worker() {\n  dangChay = true;\n  const viec = hangDoi.shift();\n  if (viec.ky === 'HK0') throw new Error('học kỳ không hợp lệ: HK0');   // ném ra trước khi kịp đặt lại cờ\n  await new Promise((r) =&gt; setTimeout(r, 50));\n  viec.res.end('ok\\n');\n  dangChay = false;\n  if (hangDoi.length) worker().catch(loiWorker);\n}\nconst loiWorker = (e) =&gt; log({ muc: 'error', msg: 'worker lỗi', loi: e.message });\nhttp.createServer((req, res) =&gt; {\n  const ky = new URL(req.url, 'http://x').searchParams.get('ky') || 'HK1';\n  if (req.url.startsWith('/health')) return res.end(JSON.stringify({ ok: true, hangDoi: hangDoi.length }) + '\\n');\n  hangDoi.push({ ky, res });\n  log({ muc: 'info', msg: 'nhận việc xuất báo cáo', ky, hangDoi: hangDoi.length });\n  if (!dangChay) worker().catch(loiWorker);\n}).listen(3000, () =&gt; log({ muc: 'info', msg: 'khởi động', pid: process.pid }));";
export const BC_COMPOSE = "name: dbg-c101\nservices:\n  app:\n    image: node:22-alpine\n    working_dir: /app\n    # --report-on-signal: gửi SIGUSR2 ⇒ Node ghi một báo cáo chẩn đoán JSON (stack JS, handle, bộ nhớ) mà KHÔNG dừng tiến trình\n    command: node --report-on-signal --report-signal=SIGUSR2 --report-directory=/app/bao-cao app.mjs\n    volumes: [ \"./:/app\" ]\n    ports: [ \"127.0.0.1:41011:3000\" ]";
export const BC_SH = "#!/bin/bash\n# c101-bang-chung.sh — dịch vụ kẹt: thu bằng chứng TRƯỚC khi khởi động lại, và xem recreate xoá mất gì.\ncd /tmp/dbg-lab/ch10/node/c101/bang-chung\nrm -rf bao-cao bang-chung-*; mkdir -p bao-cao\ndocker compose up -d --quiet-pull 2&gt;/dev/null\nuntil curl -s -m 1 127.0.0.1:41011/health &gt;/dev/null; do sleep 0.3; done\np() { echo \"\\$ $*\"; eval \"$@\"; }\np 'curl -s -m 2 \"127.0.0.1:41011/xuat?ky=HK1\"'\np 'curl -s -m 2 \"127.0.0.1:41011/xuat?ky=HK0\" || echo \"[curl $? — hết 2 s không có trả lời]\"'\nfor i in 1 2 3; do curl -s -m 2 \"127.0.0.1:41011/xuat?ky=HK1\" &gt;/dev/null || echo \"[người dùng $i: curl $? — treo]\"; done\np 'curl -s -m 2 127.0.0.1:41011/health'\necho '# --- trước khi bấm restart: 3 lệnh, dưới một phút ---'\np 'D=bang-chung-$(date -u +%Y%m%dT%H%MZ); mkdir $D'\np 'docker compose logs --no-color --timestamps app &gt; $D/app.log; wc -l &lt; $D/app.log'\np \"docker inspect -f '{{.State.Status}} exit={{.State.ExitCode}} oom={{.State.OOMKilled}} restarts={{.RestartCount}} chay-tu={{.State.StartedAt}}' dbg-c101-app-1\"\np 'docker compose kill -s SIGUSR2 app &gt;/dev/null 2&gt;&amp;1; sleep 1; ls bao-cao/'\np \"jq '{node: .header.nodejsVersion, ly_do: .header.trigger, heap_MB: (.javascriptHeap.usedMemory/1048576|floor), pid: .header.processId}' bao-cao/*.json\"\necho '# --- giờ mới khôi phục: deploy lại (compose up --force-recreate là điều CI/CD làm mỗi lần deploy) ---'\np 'docker compose up -d --force-recreate 2&gt;&amp;1 | tail -1'\nuntil curl -s -m 1 127.0.0.1:41011/health &gt;/dev/null; do sleep 0.3; done\np 'docker compose logs --no-color app | grep -c \"nhận việc\"'\np 'curl -s -m 2 127.0.0.1:41011/health'\np 'grep -c \"nhận việc\" $D/app.log; grep \"worker lỗi\" $D/app.log | grep -o \"{.*\" | jq -c .'\ndocker compose down -t 1 &gt;/dev/null 2&gt;&amp;1";
export const APP102 = "// app.mjs — LabFlow API với log JSON (pino) cho bài 10.2.\n//   LOG_AN_TOAN=0 node c102/app.mjs   bản \"debug nhanh\" quên gỡ: in cả header lẫn body\n//   LOG_AN_TOAN=1 node c102/app.mjs   bản an toàn: redact + request_id + bật debug tạm thời cho MỘT người dùng\nimport express from 'express';\nimport pino from 'pino';\nimport { randomUUID, createHash } from 'node:crypto';\n\nconst AN_TOAN = process.env.LOG_AN_TOAN === '1';\nconst ADMIN_TOKEN = process.env.ADMIN_TOKEN || 'lab-admin-102';     // chỉ của lab\nconst base = pino({\n  level: 'info',\n  base: { svc: 'labflow-api', ver: '2.3.1' },                       // phiên bản trong MỌI dòng: biết dòng nào của bản nào\n  timestamp: pino.stdTimeFunctions.isoTime,\n  ...(AN_TOAN &amp;&amp; {\n    redact: { paths: ['req.headers.authorization', 'req.headers.cookie', 'body.matKhau', '*.token'], censor: '[đã che]' },\n  }),\n});\nconst bamEmail = (e) =&gt; createHash('sha256').update(String(e).toLowerCase()).digest('hex').slice(0, 12); // so khớp được, không đọc ngược được\n\n// debug tạm thời: { user, het } — chỉ người dùng đó có log debug, tự tắt khi hết giờ\nlet debugTam = null;\n\nconst app = express();\napp.use(express.json());\napp.use((req, res, next) =&gt; {\n  const id = /^[\\w-]{8,64}$/.test(req.get('x-request-id') || '') ? req.get('x-request-id') : randomUUID().slice(0, 8);\n  const user = req.get('x-user') || '-';\n  const batDebug = AN_TOAN &amp;&amp; debugTam &amp;&amp; debugTam.user === user &amp;&amp; Date.now() &lt; debugTam.het;\n  req.log = base.child({ request_id: id, user }, { level: batDebug ? 'debug' : 'info' });\n  res.set('x-request-id', id);\n  const t0 = process.hrtime.bigint();\n  if (req.path === '/health') return next();\n  res.on('finish', () =&gt; req.log.info({ method: req.method, path: req.route?.path ?? req.path, status: res.statusCode,\n    ms: Number((process.hrtime.bigint() - t0) / 1000000n) }, 'request xong'));\n  next();\n});\n\napp.post('/dang-nhap', (req, res) =&gt; {\n  if (!AN_TOAN) req.log.info({ req: { headers: req.headers }, body: req.body }, 'dang nhap');   // \"debug nhanh\"\n  else req.log.info({ email_hash: bamEmail(req.body.email), co_mat_khau: Boolean(req.body.matKhau) }, 'dang nhap');\n  res.json({ token: 'eyJhbGciOiJIUzI1NiJ9.' + Buffer.from(req.body.email).toString('base64url') + '.chu-ky-lab' });\n});\n\n// phí trễ hạn: lỗi chỉ xảy ra với một số sinh viên — log debug cho thấy giá trị trung gian\nconst KHOA = { 'SE1807': 'K18', 'SE1911': 'K19', 'SE2003': 'K20-CLC' };\napp.get('/phi-tre', (req, res) =&gt; {\n  const sv = req.get('x-user');\n  const soNgay = Number(req.query.ngay);\n  const khoa = KHOA[sv] ?? 'K18';\n  const giamPhanTram = Number(khoa.slice(1)) &gt;= 20 ? 50 : 0;     // K20 trở đi được giảm 50%\n  const phi = soNgay * 5000 * (1 - giamPhanTram / 100);\n  req.log.debug({ soNgay, khoa, giamPhanTram, phi }, 'tinh phi tre');\n  res.json({ sv, phi });\n});\n\napp.get('/health', (req, res) =&gt; res.json({ ok: true }));\napp.get('/dat-lich/:id', (req, res) =&gt; {\n  const loc = JSON.parse(req.query.loc ?? '{}');          // ?loc=… hỏng ⇒ SyntaxError ⇒ 500\n  res.json({ id: req.params.id, loc });\n});\n\n// bật debug tạm thời: chỉ nghe localhost, cần token quản trị, có hạn, ghi log kiểm toán\napp.post('/quan-tri/debug-tam', (req, res) =&gt; {\n  if (!AN_TOAN || req.get('x-admin-token') !== ADMIN_TOKEN) return res.status(403).json({ loi: 'cấm' });\n  const phut = Math.min(Number(req.body.phut) || 10, 30);\n  debugTam = { user: req.body.user, het: Date.now() + phut * 60000 };\n  if (req.body.giay) debugTam.het = Date.now() + Number(req.body.giay) * 1000;  // lab: rút ngắn để thấy tự tắt\n  req.log.warn({ kiem_toan: true, bat_debug_cho: debugTam.user, het: new Date(debugTam.het).toISOString() }, 'BẬT log debug tạm thời');\n  res.json({ ok: true, het: new Date(debugTam.het).toISOString() });\n});\n\n// lỗi chưa bắt: log đủ để tái hiện (method, url, header) — redact lo phần bí mật\napp.use((err, req, res, next) =&gt; {\n  req.log.error({ err, req: { method: req.method, url: req.originalUrl, headers: req.headers } }, 'lỗi chưa bắt');\n  res.status(500).json({ loi: 'lỗi máy chủ', request_id: res.get('x-request-id') });\n});\n\napp.listen(41012, '127.0.0.1', () =&gt; base.info({ pid: process.pid, an_toan: AN_TOAN }, 'khởi động'));";
export const CTRL_JAVA = "package vn.labflow.prod;\n\nimport java.util.Map;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.http.ResponseEntity;\nimport org.springframework.web.bind.annotation.*;\n\n@RestController\npublic class DatLichController {\n  private static final Logger log = LoggerFactory.getLogger(DatLichController.class);\n  private final Map&lt;Long, String&gt; datLich = Map.of(7L, \"Lab 401 — SE1801-07 — CHO_DUYET\");\n\n  @Value(\"${app.log-an-toan:false}\") boolean logAnToan;\n\n  @GetMapping(\"/dat-lich/{id}\")\n  public ResponseEntity&lt;String&gt; xem(@PathVariable long id) {\n    String d = datLich.get(id); // BP\n    log.debug(\"tra dat lich id={} co={}\", id, d != null);\n    return d == null ? ResponseEntity.notFound().build() : ResponseEntity.ok(d);\n  }\n\n  record DangNhap(String email, String matKhau) {}\n\n  /** 12 ký tự đầu của SHA-256: cùng email ⇒ cùng giá trị (so khớp được trong log), không đọc ngược ra email. */\n  static String bam(String email) {\n    try {\n      byte[] h = java.security.MessageDigest.getInstance(\"SHA-256\").digest(email.toLowerCase().getBytes(java.nio.charset.StandardCharsets.UTF_8));\n      return java.util.HexFormat.of().formatHex(h).substring(0, 12);\n    } catch (java.security.NoSuchAlgorithmException e) { throw new IllegalStateException(e); }\n  }\n\n  @PostMapping(\"/dang-nhap\")\n  public Map&lt;String, String&gt; dangNhap(@RequestBody DangNhap b, @RequestHeader Map&lt;String, String&gt; headers) {\n    if (!logAnToan) {\n      // bản \"debug nhanh\" để quên trên production: in hết cho chắc\n      log.info(\"dang nhap headers={} body={}\", headers, b);\n    } else {\n      // bản an toàn: chỉ thứ cần để khoanh lỗi, không có bí mật, không có PII thô\n      log.atInfo().setMessage(\"dang nhap\")\n          .addKeyValue(\"email_hash\", bam(b.email()))\n          .addKeyValue(\"co_mat_khau\", b.matKhau() != null &amp;&amp; !b.matKhau().isEmpty())\n          .addKeyValue(\"user_agent\", headers.getOrDefault(\"user-agent\", headers.getOrDefault(\"User-Agent\", \"-\")))\n          .log();\n    }\n    return Map.of(\"token\", \"tok_\" + Integer.toHexString(b.email().hashCode()));\n  }\n}";
export const MA_REQ = "package vn.labflow.prod;\n\nimport jakarta.servlet.FilterChain;\nimport jakarta.servlet.ServletException;\nimport jakarta.servlet.http.HttpServletRequest;\nimport jakarta.servlet.http.HttpServletResponse;\nimport java.io.IOException;\nimport java.util.UUID;\nimport org.slf4j.MDC;\nimport org.springframework.stereotype.Component;\nimport org.springframework.web.filter.OncePerRequestFilter;\n\n/** Gắn request_id vào MDC: mọi dòng log trong request này tự mang id, và trả lại id cho client (để người dùng dán vào ticket). */\n@Component\npublic class MaRequest extends OncePerRequestFilter {\n  @Override\n  protected void doFilterInternal(HttpServletRequest req, HttpServletResponse res, FilterChain chain) throws ServletException, IOException {\n    String id = req.getHeader(\"X-Request-Id\");\n    if (id == null || !id.matches(\"[A-Za-z0-9-]{8,64}\")) id = UUID.randomUUID().toString().substring(0, 8);\n    MDC.put(\"request_id\", id);\n    res.setHeader(\"X-Request-Id\", id);\n    try { chain.doFilter(req, res); } finally { MDC.remove(\"request_id\"); }\n  }\n}";
export const PROPS = "server.address=127.0.0.1\nserver.port=41020\nspring.main.banner-mode=off\n# log JSON (định dạng ECS) — tính năng có sẵn từ Spring Boot 3.4, không cần thư viện thêm\nlogging.structured.format.console=ecs\n# actuator chỉ nghe ở cổng quản trị riêng, chỉ localhost\nmanagement.server.port=41021\nmanagement.server.address=127.0.0.1\nmanagement.endpoints.web.exposure.include=health,loggers";
export const CO = "// co.mjs — feature flag tối giản: đọc flags.json (đổi tệp là đổi hành vi, KHÔNG cần deploy), chia nhóm ổn định theo băm.\nimport fs from 'node:fs';\nimport { createHash } from 'node:crypto';\n\nconst TEP = process.env.FLAGS || new URL('./flags.json', import.meta.url).pathname;\nlet bang = {}, docLuc = 0;\nfunction nap() {                                   // đọc lại tối đa 1 lần / giây; tệp hỏng ⇒ giữ bảng cũ\n  if (Date.now() - docLuc &lt; 1000) return bang;\n  docLuc = Date.now();\n  try { bang = JSON.parse(fs.readFileSync(TEP, 'utf8')); } catch { /* giữ bảng cũ */ }\n  return bang;\n}\n// cùng (cờ, người dùng) ⇒ luôn cùng một ô 0..99 — tăng 5% → 20% thì 5% cũ vẫn ở trong\nexport const o = (ten, user) =&gt; createHash('sha256').update(`${ten}:${user}`).digest().readUInt16BE(0) % 100;\n\nexport function bat(ten, user, mặcĐịnh = false) {\n  const c = nap()[ten];\n  if (!c) return mặcĐịnh;                          // cờ không có ⇒ giá trị an toàn\n  if (c.tat) return false;                         // công tắc ngắt thắng mọi thứ\n  if (c.choUser?.includes(user)) return true;      // QA, người trong nhóm\n  return o(ten, user) &lt; (c.phanTram ?? 0);\n}";
export const CHIA_NHOM = "// chia-nhom.mjs — 10.000 người dùng: bao nhiêu người thấy tính năng ở 5%, 20%; người ở 5% có còn ở 20% không.\nimport { o } from './co.mjs';\nconst users = Array.from({ length: 10000 }, (_, i) =&gt; `SE${18 + (i % 4)}${String(i).padStart(4, '0')}`);\nconst nhom = (pt) =&gt; new Set(users.filter((u) =&gt; o('goi-y-phong', u) &lt; pt));\nconst n5 = nhom(5), n20 = nhom(20);\nconsole.log(`5%  ⇒ ${n5.size} người;  20% ⇒ ${n20.size} người`);\nconsole.log(`người ở nhóm 5% còn ở nhóm 20%: ${[...n5].filter((u) =&gt; n20.has(u)).length}/${n5.size}`);\nconsole.log(`gọi lại 1.000 lần cho SE180007: ${new Set(Array.from({ length: 1000 }, () =&gt; o('goi-y-phong', 'SE180007'))).size} giá trị khác nhau`);\n// \"Math.random() mỗi request\" — giả lập bằng bộ sinh có hạt giống để chạy lại vẫn ra cùng số\nconst ngau = (hat) =&gt; () =&gt; ((hat = (hat * 1103515245 + 12345) &gt;&gt;&gt; 0) / 2 ** 32);\nconst r1 = ngau(1), r2 = ngau(2);\nconst ngauNhien = new Set(users.filter(() =&gt; r1() &lt; 0.05));\nconst ngauNhien2 = new Set(users.filter(() =&gt; r2() &lt; 0.05));\nconsole.log(`nếu dùng Math.random() &lt; 0.05 mỗi request: lượt 1 ${ngauNhien.size} người, lượt 2 ${ngauNhien2.size} người, trùng nhau chỉ ${[...ngauNhien].filter((u) =&gt; ngauNhien2.has(u)).length}`);";
export const APP103 = "// app.mjs — LabFlow /phong cho bài 10.3. VER=2.3.1 (cũ) hoặc VER=2.4.0 (có tính năng \"gợi ý phòng\" sau cờ goi-y-phong).\nimport http from 'node:http';\nimport { bat } from './co.mjs';\n\nconst VER = process.env.VER || '2.3.1';\nconst PORT = Number(process.env.PORT || 3000);\n// lịch sử đặt phòng: sinh viên mới (chưa đặt lần nào) không có mục nào\nconst lichSu = (sv) =&gt; (Number(sv.slice(-4)) % 7 &lt; 2 ? [] : [{ phong: 'Lab ' + (400 + Number(sv.slice(-2)) % 7) }]);\n\nfunction goiY(sv) {                      // tính năng mới của 2.4.0\n  const ls = lichSu(sv);\n  return ls.at(-1).phong;                // lỗi: sinh viên chưa có lịch sử ⇒ undefined.phong ⇒ TypeError\n}\n\nhttp.createServer((req, res) =&gt; {\n  const u = new URL(req.url, 'http://x');\n  const sv = u.searchParams.get('sv') || 'SE180001';\n  res.setHeader('x-ver', VER);\n  if (u.pathname === '/health') return res.end(JSON.stringify({ ver: VER, pid: process.pid }) + '\\n');\n  try {\n    const body = { phong: ['Lab 401', 'Lab 402', 'Lab 403'] };\n    if (VER &gt;= '2.4.0' &amp;&amp; bat('goi-y-phong', sv)) body.goiY = goiY(sv);\n    res.end(JSON.stringify(body) + '\\n');\n  } catch (e) {\n    console.log(JSON.stringify({ t: new Date().toISOString(), ver: VER, muc: 'error', sv, loi: e.message }));\n    res.statusCode = 500; res.end('{\"loi\":\"lỗi máy chủ\"}\\n');\n  }\n}).listen(PORT, () =&gt; console.log(JSON.stringify({ msg: 'khởi động', ver: VER, port: PORT })));";
export const CONG_TAC = "// cong-tac.mjs — 2.4.0 đang chạy với goi-y-phong ở 20%; lỗi 500 xuất hiện; bật công tắc ngắt trong flags.json — không deploy, không restart.\nimport { spawn } from 'node:child_process';\nimport fs from 'node:fs';\nconst FLAGS = '/tmp/dbg-lab/ch10/out/flags-103.json';\nfs.writeFileSync(FLAGS, JSON.stringify({ 'goi-y-phong': { phanTram: 20 } }));\nconst app = spawn('node', ['app.mjs'], { env: { ...process.env, VER: '2.4.0', PORT: '41013', FLAGS }, stdio: ['ignore', 'pipe', 'inherit'] });\nlet dongLoi = 0; app.stdout.on('data', (b) =&gt; { dongLoi += String(b).split('\\n').filter((x) =&gt; x.includes('\"error\"')).length; });\nawait new Promise((r) =&gt; setTimeout(r, 500));\nconst users = Array.from({ length: 2000 }, (_, i) =&gt; `SE18${String(i).padStart(4, '0')}`);\nlet k = 0; const t0 = Date.now();\nfor (let cua = 1; cua &lt;= 8; cua++) {                 // 8 cửa sổ, mỗi cửa sổ 200 request\n  let loi = 0;\n  await Promise.all(Array.from({ length: 200 }, async () =&gt; {\n    const r = await fetch(`http://127.0.0.1:41013/phong?sv=${users[k++ % users.length]}`);\n    if (r.status &gt;= 500) loi++; await r.text();\n  }));\n  const s = ((Date.now() - t0) / 1000).toFixed(1);\n  console.log(`t=${s.padStart(4)} s  cửa sổ ${cua}: ${String(loi).padStart(3)}/200 lỗi 500  ${'█'.repeat(Math.round(loi / 2))}`);\n  if (cua === 3) {\n    fs.writeFileSync(FLAGS, JSON.stringify({ 'goi-y-phong': { phanTram: 20, tat: true } }));\n    console.log(`        &gt;&gt;&gt; người trực sửa flags.json: \"tat\": true  (không build, không deploy, không restart)`);\n  }\n  await new Promise((r) =&gt; setTimeout(r, 400));\n}\nconsole.log(`tiến trình vẫn là pid ${app.pid}; log ghi ${dongLoi} dòng error, tất cả trước lúc tắt cờ`);\napp.kill();";
export const NGINX_CANARY = "# 1 worker: round-robin có trọng số đếm trong một tiến trình ⇒ tỉ lệ đúng như khai báo\nworker_processes 1;\nevents {}\nhttp {\n  log_format json escape=json '{\"t\":\"$time_iso8601\",\"status\":$status,\"upstream\":\"$upstream_addr\",\"ver\":\"$upstream_http_x_ver\",\"ms\":$request_time,\"uri\":\"$request_uri\"}';\n  access_log /tmp/access.log json;   # tệp thật (ảnh nginx nối /var/log/nginx/access.log vào stdout)\n  upstream labflow {\n    server v231:3000 weight=19;   # 95% — bản đang ổn định\n    server v240:3000 weight=1;    #  5% — canary\n  }\n  server { listen 80; location / { proxy_pass http://labflow; } }\n}";
export const CANARY_COMPOSE = "name: dbg-c103\nservices:\n  v231:\n    image: node:22-alpine\n    working_dir: /app\n    command: node app.mjs\n    environment: { VER: \"2.3.1\" }\n    volumes: [ \"../:/app:ro\" ]\n  v240:\n    image: node:22-alpine\n    working_dir: /app\n    command: node app.mjs\n    environment: { VER: \"2.4.0\", FLAGS: /canary/flags-canary.json }\n    volumes: [ \"../:/app:ro\", \"./:/canary:ro\" ]\n  lb:\n    image: nginx:1.27-alpine\n    volumes: [ \"./nginx.conf:/etc/nginx/nginx.conf:ro\" ]\n    ports: [ \"127.0.0.1:41014:80\" ]\n    depends_on: [ v231, v240 ]";
export const K_CU = "// ban-cu/may.mjs — bản 2003: cờ \"SMARS\" bật ⇒ chạy Power Peg (mã chết từ lâu, không ai gọi nữa).\n// Power Peg chia lệnh mẹ thành lệnh con cho tới khi \"đã khớp đủ\" — nhưng phần đếm khớp đã bị chuyển đi nơi khác năm 2005.\nimport http from 'node:http';\nimport fs from 'node:fs';\nconst VER = 'cu-2003'; const PORT = Number(process.argv[2]);\nconst co = () =&gt; JSON.parse(fs.readFileSync(new URL('../flags.json', import.meta.url), 'utf8'));\nhttp.createServer((req, res) =&gt; {\n  if (req.url === '/health') return res.end(JSON.stringify({ may: PORT - 41020, ver: VER }) + '\\n');\n  const soLenh = 10; let lenhCon = 0;\n  if (co().SMARS) {\n    // mỗi lệnh mẹ: Power Peg gửi lệnh con mãi vì \"đã khớp\" luôn = 0.\n    // Lab dừng ở 1 triệu lệnh con cho mỗi lệnh mẹ; Knight 2012 không có trần này.\n    for (let i = 0; i &lt; soLenh; i++) { const daKhop = 0; while (daKhop &lt; 100 &amp;&amp; lenhCon &lt; (i + 1) * 1e6) lenhCon++; }\n  } else lenhCon = soLenh;\n  res.end(JSON.stringify({ may: PORT - 41020, ver: VER, lenhMe: soLenh, lenhCon }) + '\\n');\n}).listen(PORT, '127.0.0.1');";
export const K_MOI = "// ban-moi/may.mjs — bản 2012: tái dùng cờ \"SMARS\" cho tính năng mới RLP. Mã Power Peg đã bị xoá.\nimport http from 'node:http';\nimport fs from 'node:fs';\nconst VER = 'moi-2012'; const PORT = Number(process.argv[2]);\nconst co = () =&gt; JSON.parse(fs.readFileSync(new URL('../flags.json', import.meta.url), 'utf8'));\nhttp.createServer((req, res) =&gt; {\n  if (req.url === '/health') return res.end(JSON.stringify({ may: PORT - 41020, ver: VER }) + '\\n');\n  const soLenh = 10;\n  const lenhCon = co().SMARS ? soLenh : soLenh;          // RLP: mỗi lệnh mẹ một lệnh con, có kiểm khớp\n  res.end(JSON.stringify({ may: PORT - 41020, ver: VER, lenhMe: soLenh, lenhCon }) + '\\n');\n}).listen(PORT, '127.0.0.1');";
export const K_TRIEN_KHAI = "#!/bin/bash\n# trien-khai.sh &lt;ban-cu|ban-moi&gt; — \"deploy tay\" lên 8 máy (thư mục may1..may8). Như Knight 2012: kỹ thuật viên chép từng máy, không ai kiểm lại.\ncd /tmp/dbg-lab/ch10/node/c103/knight\nfor m in 1 2 3 4 5 6 7 8; do\n  mkdir -p may$m\n  if [ \"$1\" = ban-moi ] &amp;&amp; [ $m = 8 ]; then continue; fi    # máy 8 bị sót — lệnh không báo lỗi gì\n  cp $1/may.mjs may$m/may.mjs\ndone\necho \"deploy $1: xong\"";
export const API104 = "// api.mjs — LabFlow API cho bài 10.4: mỗi request một truy vấn PG; log JSON tách thời gian CHỜ POOL và thời gian SQL.\nimport http from 'node:http';\nimport pg from 'pg';\nconst POOL = Number(process.env.DB_POOL || 10);\nconst pool = new pg.Pool({ connectionString: process.env.DATABASE_URL, max: POOL });\nconst VER = process.env.VER || '2.6.0', MAY = process.env.HOSTNAME;\nconst log = (o) =&gt; console.log(JSON.stringify({ t: new Date().toISOString(), svc: 'api', ver: VER, may: MAY, ...o }));\nhttp.createServer(async (req, res) =&gt; {\n  if (req.url === '/health') return res.end('{\"ok\":true}\\n');\n  const t0 = performance.now(); let tCho = 0, tSql = 0; const choTruoc = pool.waitingCount;\n  try {\n    const c = await pool.connect(); tCho = performance.now() - t0;\n    try {\n      const t1 = performance.now();\n      const r = await c.query('SELECT phong_id, count(*)::int AS n, pg_sleep(0.02) FROM dat_lich WHERE phong_id = $1 GROUP BY 1', [1 + (req.url.length % 20)]);\n      tSql = performance.now() - t1;\n      res.end(JSON.stringify(r.rows[0] ?? {}) + '\\n');\n    } finally { c.release(); }\n  } catch (e) { res.statusCode = 500; res.end('{\"loi\":\"db\"}\\n'); log({ muc: 'error', loi: e.message }); }\n  const ms = performance.now() - t0;\n  if (ms &gt; 200) log({ muc: 'warn', msg: 'request chậm', url: req.url, ms: Math.round(ms), ms_cho_pool: Math.round(tCho), ms_sql: Math.round(tSql), pool_cho_truoc: choTruoc, pool_max: POOL });\n}).listen(3000, () =&gt; log({ muc: 'info', msg: 'khởi động', pool_max: POOL }));";
export const COMPOSE104 = "name: dbg-c104\nservices:\n  api-a:\n    image: node:22-alpine\n    hostname: api-a\n    working_dir: /app\n    command: node c104/api.mjs\n    environment: { DATABASE_URL: \"postgresql://postgres:dbg@db:5432/labflow\", DB_POOL: \"10\" }\n    volumes: [ \"../:/app:ro\" ]\n  api-b:\n    image: node:22-alpine\n    hostname: api-b\n    working_dir: /app\n    command: node c104/api.mjs\n    # ai đó \"tạm\" hạ pool trên MỘT máy lúc thử nghiệm và quên trả lại\n    environment: { DATABASE_URL: \"postgresql://postgres:dbg@db:5432/labflow\", DB_POOL: \"${DB_POOL_B:-10}\" }\n    volumes: [ \"../:/app:ro\" ]\n  lb:\n    image: nginx:1.27-alpine\n    volumes: [ \"./nginx.conf:/etc/nginx/nginx.conf:ro\" ]\n    ports: [ \"127.0.0.1:41015:80\" ]\n    depends_on: [ api-a, api-b ]\n  db:\n    image: postgres:16\n    environment: { POSTGRES_PASSWORD: dbg, POSTGRES_DB: labflow }\n    volumes: [ \"../../sql/seed.sql:/docker-entrypoint-initdb.d/seed.sql:ro\" ]";
export const C104_SH = "#!/bin/bash\n# c104.sh — một sự cố \"p95 tăng vọt\" và 5 bước từ cảnh báo tới nguyên nhân, chỉ bằng log + số đo.\ncd /tmp/dbg-lab/ch10/node/c104\np() { echo \"\\$ $*\"; eval \"$@\"; }\nhien() { echo \"\\$ $*\"; }\ndocker compose down -t 1 &gt;/dev/null 2&gt;&amp;1; rm -f nhat-ky-thay-doi.log\nDB_POOL_B=10 docker compose up -d --quiet-pull &gt;/dev/null 2&gt;&amp;1\nuntil curl -s -m 1 127.0.0.1:41015/health | grep -q ok &amp;&amp; docker compose exec -T db psql -U postgres -d labflow -Atc 'select 1 from dat_lich limit 1' 2&gt;/dev/null | grep -q 1; do sleep 0.5; done\nsleep 1\necho '# --- trước sự cố: tải đều 30 request đồng thời ---'\nnode tai.mjs 10 30\necho \"$(date -u +%FT%TZ) api-b  DB_POOL 10 -&gt; 2  (thử tải, \\\"lát trả lại\\\")  người đổi: dev-b\" &gt;&gt; nhat-ky-thay-doi.log\nDB_POOL_B=2 docker compose up -d api-b &gt;/dev/null 2&gt;&amp;1; sleep 1.5\necho '# --- (không ai báo gì cho người trực) ---'\nnode tai.mjs 15 30\necho '# ===== BƯỚC 1 — xác nhận và khoanh phạm vi: chậm ở đâu, cho ai? ====='\np \"docker compose exec -T lb cat /tmp/access.log | jq -s -r 'group_by(.up)[] | (map(.rt) | sort) as \\$r | \\\"\\\\(.[0].up)  \\\\(length) req  p50 \\\\(\\$r[length/2|floor]*1000|floor) ms  p95 \\\\(\\$r[length*0.95|floor]*1000|floor) ms  5xx \\\\(map(select(.status&gt;=500))|length)\\\"'\"\np 'docker compose exec -T lb getent hosts api-a api-b   # IP nào là máy nào'\necho '# ===== BƯỚC 2 — cái gì vừa thay đổi? (deploy, cấu hình, cờ, hạ tầng) ====='\np 'cat nhat-ky-thay-doi.log'\np 'for s in api-a api-b; do echo \"$s: $(docker compose exec -T $s env | grep ^DB_POOL)  chạy từ $(docker inspect -f {{.State.StartedAt}} $(docker compose ps -q $s) | cut -c12-19)\"; done'\necho '# ===== BƯỚC 3 — khoanh tầng: thời gian nằm ở pool, ở SQL hay ở mạng? ====='\np \"docker compose logs --no-color api-a api-b | grep -o '{.*\\\"request chậm\\\".*' | jq -s -c 'group_by(.may)[] | {may: .[0].may, so_cham: length, tb_ms: (map(.ms)|add/length|floor), tb_cho_pool: (map(.ms_cho_pool)|add/length|floor), tb_sql: (map(.ms_sql)|add/length|floor), max_cho: (map(.pool_cho_truoc)|max), pool_max: .[0].pool_max}'\"\np \"docker compose exec -T db psql -U postgres -d labflow -c \\\"SELECT client_addr, count(*) AS ket_noi FROM pg_stat_activity WHERE datname = 'labflow' AND backend_type = 'client backend' GROUP BY 1 ORDER BY 2\\\"\"\necho '# ===== BƯỚC 4 — cầm máu: trả cấu hình về, đo lại ====='\necho \"$(date -u +%FT%TZ) api-b  DB_POOL 2 -&gt; 10  (khôi phục, người trực)\" &gt;&gt; nhat-ky-thay-doi.log\np 'DB_POOL_B=10 docker compose up -d api-b 2&gt;&amp;1 | tail -1'\nsleep 1.5\np 'node tai.mjs 10 30'\necho '# ===== BƯỚC 5 — ghi lại: dòng thời gian cho ticket/postmortem ====='\np 'cat nhat-ky-thay-doi.log'\ndocker compose down -t 1 &gt;/dev/null 2&gt;&amp;1";
export const L_COMPOSE = "# Lab 10.5 — \"production\" thu nhỏ. Bạn KHÔNG attach debugger, KHÔNG sửa mã đang chạy. Chỉ có: ./quan-sat (log nginx, metrics, cảnh báo),\n# docker compose logs, ./cau-hinh (cờ + nhật ký thay đổi) và mã nguồn trong ./app để ĐỌC.\nname: dbg-lab10\nx-api: &amp;api\n  image: node:22-alpine\n  working_dir: /app\n  command: node api.mjs\n  volumes: [ \"./app:/app:ro\", \"./cau-hinh:/cau-hinh:ro\" ]\n  mem_limit: 256m\nservices:\n  api-a: { &lt;&lt;: *api, hostname: api-a }\n  api-b: { &lt;&lt;: *api, hostname: api-b }\n  lb:\n    image: nginx:1.27-alpine\n    volumes: [ \"./nginx.conf:/etc/nginx/nginx.conf:ro\", \"./quan-sat:/quan-sat\" ]\n    ports: [ \"127.0.0.1:41050:80\" ]\n    depends_on: [ api-a, api-b ]\n  khach:\n    image: node:22-alpine\n    working_dir: /lab\n    command: node khach.mjs\n    volumes: [ \"./khach.mjs:/lab/khach.mjs:ro\", \"./app:/lab/app:ro\" ]\n    depends_on: [ lb ]\n  quan-sat:\n    image: node:22-alpine\n    working_dir: /lab\n    command: node quan-sat.mjs\n    volumes: [ \"./quan-sat.mjs:/lab/quan-sat.mjs:ro\", \"./quan-sat:/quan-sat\" ]\n    depends_on: [ api-a, api-b ]\n  van-hanh:\n    image: node:22-alpine\n    working_dir: /lab\n    command: node van-hanh.mjs\n    volumes: [ \"./van-hanh.mjs:/lab/van-hanh.mjs:ro\", \"./cau-hinh:/cau-hinh\" ]";
export const L_CHUAN_BI = "#!/bin/bash\n# chuan-bi.sh — dựng \"production\" của lab 10.5, deploy 2.5.0, để lưu lượng chạy. Khoảng 2 phút sau sẽ có cảnh báo.\ncd \"$(dirname \"$0\")\"\ndocker compose down -t 1 &gt;/dev/null 2&gt;&amp;1\n# tệp do container (root) tạo ở lượt trước: xoá bằng chính một container\ndocker run --rm -v \"$PWD\":/lab node:22-alpine rm -rf /lab/quan-sat /lab/cau-hinh\nmkdir -p quan-sat cau-hinh\ncat &gt; cau-hinh/flags.json &lt;&lt;'J'\n{\n  \"xuat-ical\": { \"phanTram\": 0, \"choUser\": [\"SE180001\"] },\n  \"goi-y-phong\": { \"tat\": true }\n}\nJ\necho \"$(date -u +%FT%TZ) DEPLOY labflow-api 2.4.3 -&gt; 2.5.0 (api-a, api-b)  CI #812  thay đổi: thêm tải lịch iCalendar (sau cờ xuat-ical), sửa chính tả\" &gt; cau-hinh/nhat-ky-thay-doi.log\n: &gt; cau-hinh/nhat-ky-co.log\nchmod 777 quan-sat cau-hinh; chmod 666 cau-hinh/*\ndocker compose up -d --quiet-pull 2&gt;&amp;1 | grep -v -e Pulling -e Pulled -e Waiting\necho \"đã chạy. Xem cảnh báo: tail -f quan-sat/canh-bao.log   (dừng: docker compose down)\"";
export const L_API = "// api.mjs — LabFlow API 2.5.0 (\"production\" của lab 10.5). Chạy KHÔNG có --inspect: không attach được, chỉ có log + /metrics.\nimport http from 'node:http';\nimport { pbkdf2Sync, randomUUID } from 'node:crypto';\nimport { monitorEventLoopDelay } from 'node:perf_hooks';\nimport { bat } from './co.mjs';\nimport { lichCua } from './du-lieu.mjs';\n\nconst VER = '2.5.0', MAY = process.env.HOSTNAME;\nconst log = (o) =&gt; process.stdout.write(JSON.stringify({ t: new Date().toISOString(), ver: VER, may: MAY, ...o }) + '\\n');\n\n// ---- số đo kiểu Prometheus, tự viết cho gọn (thực tế: prom-client) ----\nconst BUCKET = [25, 50, 100, 250, 500, 1000, 2500];\nconst dem = new Map(), hist = new Map();\nconst lag = monitorEventLoopDelay({ resolution: 10 }); lag.enable();\nfunction ghiSo(route, status, ms) {\n  const k = `route=\"${route}\",status=\"${status}\"`; dem.set(k, (dem.get(k) || 0) + 1);\n  const h = hist.get(route) || { b: BUCKET.map(() =&gt; 0), sum: 0, n: 0 }; hist.set(route, h);\n  BUCKET.forEach((le, i) =&gt; { if (ms &lt;= le) h.b[i]++; }); h.sum += ms; h.n++;\n}\nfunction metrics() {\n  const L = ['# TYPE http_requests_total counter'];\n  for (const [k, v] of dem) L.push(`http_requests_total{${k}} ${v}`);\n  L.push('# TYPE http_request_duration_ms histogram');\n  for (const [r, h] of hist) {\n    BUCKET.forEach((le, i) =&gt; L.push(`http_request_duration_ms_bucket{route=\"${r}\",le=\"${le}\"} ${h.b[i]}`));\n    L.push(`http_request_duration_ms_bucket{route=\"${r}\",le=\"+Inf\"} ${h.n}`, `http_request_duration_ms_sum{route=\"${r}\"} ${Math.round(h.sum)}`, `http_request_duration_ms_count{route=\"${r}\"} ${h.n}`);\n  }\n  L.push('# TYPE nodejs_eventloop_lag_p99_ms gauge', `nodejs_eventloop_lag_p99_ms ${(lag.percentile(99) / 1e6).toFixed(1)}`);\n  L.push('# TYPE process_resident_memory_bytes gauge', `process_resident_memory_bytes ${process.memoryUsage().rss}`);\n  lag.reset();\n  return L.join('\\n') + '\\n';\n}\n\n// ---- tính năng mới 2.5.0: tải lịch dạng iCalendar, sau cờ \"xuat-ical\" ----\nfunction icalMoi(sv) {\n  const ds = lichCua(sv);\n  const ev = ds.map((d) =&gt; {\n    // UID ổn định cho mỗi sự kiện (để Google Calendar không nhân đôi khi tải lại)\n    const uid = pbkdf2Sync(String(d.id), 'labflow', 200000, 16, 'sha256').toString('hex');\n    return `BEGIN:VEVENT\\nUID:${uid}@labflow\\nDTSTART;VALUE=DATE:${d.ngay.replaceAll('-', '')}\\nSUMMARY:Đặt ${d.phong.ten}\\nEND:VEVENT`;\n  });\n  return `BEGIN:VCALENDAR\\nVERSION:2.0\\n${ev.join('\\n')}\\nEND:VCALENDAR\\n`;\n}\nconst icalCu = (sv) =&gt; `BEGIN:VCALENDAR\\nVERSION:2.0\\n${lichCua(sv).map((d) =&gt; `BEGIN:VEVENT\\nUID:${d.id}@labflow\\nDTSTART;VALUE=DATE:${d.ngay.replaceAll('-', '')}\\nEND:VEVENT`).join('\\n')}\\nEND:VCALENDAR\\n`;\n\nhttp.createServer((req, res) =&gt; {\n  const t0 = performance.now();\n  const u = new URL(req.url, 'http://x');\n  const rid = req.headers['x-request-id'] || randomUUID().slice(0, 8);\n  const sv = req.headers['x-user'] || '-';\n  let route = u.pathname;\n  const xong = (status, body, type = 'application/json') =&gt; {\n    res.writeHead(status, { 'content-type': type, 'x-request-id': rid }); res.end(body);\n    const ms = performance.now() - t0; ghiSo(route, status, ms);\n    if (status &gt;= 500 || ms &gt; 500) log({ muc: status &gt;= 500 ? 'error' : 'warn', msg: status &gt;= 500 ? 'request lỗi' : 'request chậm', rid, sv, route, status, ms: Math.round(ms) });\n  };\n  try {\n    if (route === '/metrics') return res.end(metrics());\n    if (route === '/health') return xong(200, '{\"ok\":true}');\n    if (route === '/phong') return xong(200, JSON.stringify(['Lab 401', 'Lab 402', 'Lab 403', 'Lab 404', 'Lab 405', 'Lab 406']));\n    if (route === '/lich') return xong(200, JSON.stringify(lichCua(sv)));\n    if (route === '/lich/ical') return xong(200, bat('xuat-ical', sv) ? icalMoi(sv) : icalCu(sv), 'text/calendar');\n    route = 'khac'; return xong(404, '{\"loi\":\"không có\"}');\n  } catch (e) {\n    log({ muc: 'error', msg: 'lỗi chưa bắt', rid, sv, route, loi: e.message, stack: e.stack.split('\\n').slice(0, 3).map((s) =&gt; s.trim()) });\n    return xong(500, JSON.stringify({ loi: 'lỗi máy chủ', request_id: rid }));\n  }\n}).listen(Number(process.env.PORT || 3000), () =&gt; log({ muc: 'info', msg: 'khởi động', pid: process.pid }));";
export const L_DU_LIEU = "// du-lieu.mjs — dữ liệu giả định, tất định: 300 sinh viên, mỗi người vài lượt đặt phòng.\n// Lượt đặt \"online chưa xếp phòng\" có phong = null (tính năng đặt trước của học kỳ này).\nexport const SV = Array.from({ length: 300 }, (_, i) =&gt; `SE18${String(i + 1).padStart(4, '0')}`);\nexport function lichCua(sv) {\n  const n = Number(sv.slice(-4));\n  return Array.from({ length: 4 + (n % 5) }, (_, k) =&gt; ({\n    id: n * 10 + k,\n    ngay: `2026-12-${String(1 + ((n + k * 3) % 28)).padStart(2, '0')}`,\n    phong: (n * 7 + k) % 23 === 0 ? null : { ten: `Lab ${401 + ((n + k) % 6)}` },\n  }));\n}";
export const L_QUAN_SAT = "// quan-sat.mjs — vai \"Prometheus + Alertmanager\" thu nhỏ: mỗi 5 s lấy /metrics của từng máy, lưu nguyên văn, và tính cảnh báo.\n// Lỗi 5xx tính từ /metrics của app; độ trễ tính ở RÌA (access log của nginx) — thời gian người dùng thật sự chờ.\nimport fs from 'node:fs';\nconst MAY = ['api-a', 'api-b'], DIR = '/quan-sat';\nfs.mkdirSync(`${DIR}/metrics`, { recursive: true });\nconst truoc = {};\nlet viTri = 0;   // đã đọc access log tới byte nào\nconst so = (txt, re) =&gt; [...txt.matchAll(re)].reduce((s, m) =&gt; s + Number(m[1]), 0);\nfor (;;) {\n  const ts = new Date().toISOString().slice(11, 19).replaceAll(':', '');\n  let tong = 0, loi = 0, cham = 0, nRia = 0;\n  try {\n    const buf = fs.readFileSync(`${DIR}/nginx-access.log`);\n    const moi = buf.subarray(viTri).toString(); const cat = moi.lastIndexOf('\\n') + 1; viTri += Buffer.byteLength(moi.slice(0, cat));\n    for (const d of moi.slice(0, cat).split('\\n').filter(Boolean)) { const j = JSON.parse(d); if (j.uri === '/metrics') continue; nRia++; if (j.rt &gt; 0.25) cham++; }\n  } catch { /* chưa có log */ }\n  for (const m of MAY) {\n    const txt = await fetch(`http://${m}:3000/metrics`).then((r) =&gt; r.text()).catch(() =&gt; '');\n    if (!txt) continue;\n    fs.writeFileSync(`${DIR}/metrics/${ts}-${m}.prom`, txt);\n    const n = so(txt, /^http_request_duration_ms_count\\{[^}]*\\} (\\d+)/gm);\n    const e = so(txt, /^http_requests_total\\{[^}]*status=\"5\\d\\d\"\\} (\\d+)/gm);\n        const p = truoc[m] || { n: 0, e: 0 }; truoc[m] = { n, e };\n    tong += n - p.n; loi += e - p.e;\n  }\n  if (tong &gt; 0) {\n    const tlLoi = (100 * loi) / tong, tlCham = nRia ? (100 * cham) / nRia : 0;\n    const dong = `${new Date().toISOString()} req=${tong} 5xx=${tlLoi.toFixed(2)}% cham&gt;250ms(nginx)=${tlCham.toFixed(2)}%`;\n    const bao = [tlLoi &gt; 1 &amp;&amp; 'ALERT LoiCao (5xx &gt; 1% trong 5 phút)', tlCham &gt; 2 &amp;&amp; 'ALERT ChamCao (&gt; 2% request quá 250 ms)'].filter(Boolean);\n    fs.appendFileSync(`${DIR}/canh-bao.log`, dong + (bao.length ? '  🔔 ' + bao.join(' | ') : '') + '\\n');\n  }\n  await new Promise((r) =&gt; setTimeout(r, 5000));\n}";
export const L_KHACH = "// khach.mjs — lưu lượng \"người dùng thật\" qua nginx: 300 sinh viên, 70% /phong + /lich, 30% /lich/ical. Chạy tới khi bị dừng.\nimport { SV } from './app/du-lieu.mjs';\nconst URL0 = process.env.LB || 'http://lb';\nlet k = 0;\nconst dung = () =&gt; new Promise((r) =&gt; setTimeout(r, 40));\nawait Promise.all(Array.from({ length: 12 }, async (_, w) =&gt; {\n  for (;;) {\n    const i = k++; const sv = SV[(i * 37) % SV.length];\n    const duong = i % 10 &lt; 4 ? '/phong' : i % 10 &lt; 7 ? '/lich' : '/lich/ical';\n    try { const r = await fetch(URL0 + duong, { headers: { 'x-user': sv }, signal: AbortSignal.timeout(5000) }); await r.arrayBuffer(); } catch {}\n    await dung();\n  }\n}));";
export const L_VAN_HANH = "// van-hanh.mjs — vai \"đồng nghiệp ở nhóm sản phẩm\": 40 giây sau khi deploy, tăng cờ xuat-ical 0% → 25% trên trang quản trị cờ.\nimport fs from 'node:fs';\nconst TEP = '/cau-hinh/flags.json';\nawait new Promise((r) =&gt; setTimeout(r, Number(process.env.CHO_GIAY || 40) * 1000));\nconst c = JSON.parse(fs.readFileSync(TEP, 'utf8'));\nc['xuat-ical'].phanTram = 25;\nfs.writeFileSync(TEP, JSON.stringify(c, null, 2) + '\\n');\nfs.appendFileSync('/cau-hinh/nhat-ky-co.log', `${new Date().toISOString()} xuat-ical phanTram 0 -&gt; 25  (người đổi: pm-linh, ghi chú: \"mở cho 1/4 SV dùng thử\")\\n`);";
export const L_KIEM = "// kiem.mjs — chấm lab 10.5.   node kiem.mjs [tra-loi.json]      node kiem.mjs --ban-sua &lt;thư mục app đã sửa&gt;\n// Chấm bằng chứng THẬT trong ./quan-sat và ./cau-hinh — không chấm câu chữ.\nimport fs from 'node:fs';\nimport { spawn } from 'node:child_process';\nconst ok = (d, s) =&gt; console.log(`${d ? 'ĐẠT ' : 'TRƯỢT'}  ${s}`) || d;\nconst docJsonl = (p) =&gt; fs.readFileSync(p, 'utf8').split('\\n').filter(Boolean).map((x) =&gt; { try { return JSON.parse(x); } catch { return null; } }).filter(Boolean);\n\nif (process.argv[2] === '--ban-sua') {\n  // chạy bản sửa với cờ 100%, mọi sinh viên tải iCal cùng lúc với người gọi /phong\n  const dir = (await import('node:path')).resolve(process.argv[3]);\n  fs.writeFileSync('/tmp/dbg-lab10-flags.json', JSON.stringify({ 'xuat-ical': { phanTram: 100 } }));\n  const env = { ...process.env, FLAGS: '/tmp/dbg-lab10-flags.json', HOSTNAME: 'kiem', PORT: '41051' };\n  const app = spawn('node', [`${dir}/api.mjs`], { env, stdio: 'ignore', cwd: dir });\n  for (let i = 0; i &lt; 50 &amp;&amp; !(await fetch('http://127.0.0.1:41051/health').then(() =&gt; 1, () =&gt; 0)); i++) await new Promise((r) =&gt; setTimeout(r, 100));\n  const { SV } = await import(new URL('./app/du-lieu.mjs', import.meta.url));\n  let loi = 0; const msPhong = [];\n  await Promise.all([\n    (async () =&gt; { for (let i = 0; i &lt; SV.length; i += 20) await Promise.all(SV.slice(i, i + 20).map(async (sv) =&gt; {   // 20 người tải cùng lúc\n      const r = await fetch('http://127.0.0.1:41051/lich/ical', { headers: { 'x-user': sv } }); if (r.status &gt;= 500) loi++; await r.text(); })); })(),\n    (async () =&gt; { for (let i = 0; i &lt; 60; i++) { const t = performance.now(); await (await fetch('http://127.0.0.1:41051/phong')).text(); msPhong.push(performance.now() - t); await new Promise((r) =&gt; setTimeout(r, 20)); } })(),\n  ]);\n  const m = await (await fetch('http://127.0.0.1:41051/metrics')).text();\n  app.kill();\n  msPhong.sort((a, b) =&gt; a - b);\n  const p95 = msPhong[Math.floor(msPhong.length * 0.95)];\n  ok(loi === 0, `300 sinh viên tải iCal với cờ 100%: ${loi} lỗi 500`);\n  ok(p95 &lt; 100, `p95 của /phong khi đang xuất iCal: ${p95.toFixed(0)} ms (cần &lt; 100)`);\n  ok(/nodejs_eventloop_lag_p99_ms ([\\d.]+)/.test(m) &amp;&amp; Number(m.match(/nodejs_eventloop_lag_p99_ms ([\\d.]+)/)[1]) &lt; 50, `event loop lag p99: ${m.match(/nodejs_eventloop_lag_p99_ms ([\\d.]+)/)?.[1]} ms (cần &lt; 50)`);\n  process.exit(0);\n}\n\nconst tl = JSON.parse(fs.readFileSync(process.argv[2] || 'tra-loi.json', 'utf8'));\nconst nginx = docJsonl('quan-sat/nginx-access.log');\nconst coLog = fs.readFileSync('cau-hinh/nhat-ky-co.log', 'utf8');\nconst lucCo = coLog.match(/^(\\S+) xuat-ical phanTram 0 -&gt; 25/m)?.[1];\nconst dau500 = nginx.find((x) =&gt; x.status &gt;= 500)?.t;\nlet d = 0;\nd += ok(tl.co === 'xuat-ical', `thay đổi gây sự cố: cờ \"${tl.co}\" (không phải bản deploy 2.5.0)`);\nd += ok(lucCo &amp;&amp; Math.abs(new Date(tl.bat_dau) - new Date(lucCo)) &lt;= 15000, `lúc bắt đầu ${tl.bat_dau} — cách lúc đổi cờ ≤ 15 s`);\nconst r500 = nginx.find((x) =&gt; x.rid === tl.rid_500);\nd += ok(r500 &amp;&amp; r500.status &gt;= 500 &amp;&amp; r500.uri === '/lich/ical', `rid_500 ${tl.rid_500}: có trong access log, 500, /lich/ical`);\nconst rCham = nginx.find((x) =&gt; x.rid === tl.rid_cham);\nd += ok(rCham &amp;&amp; rCham.rt &gt; 0.25 &amp;&amp; rCham.uri !== '/lich/ical', `rid_cham ${tl.rid_cham}: request KHÔNG phải iCal mà vẫn chậm &gt; 250 ms (${rCham?.uri}, ${rCham?.rt} s)`);\nd += ok(/pbkdf2|event.?loop|chặn|đồng bộ|sync/i.test(tl.nguyen_nhan_cham || ''), 'nguyên nhân chậm nêu được: tính toán đồng bộ chặn event loop');\nd += ok(/null|phong|chưa xếp/i.test(tl.nguyen_nhan_500 || ''), 'nguyên nhân 500 nêu được: lượt đặt chưa có phòng (phong = null)');\nconst co = JSON.parse(fs.readFileSync('cau-hinh/flags.json', 'utf8'))['xuat-ical'];\nd += ok(co.tat === true || co.phanTram === 0, `cầm máu: cờ xuat-ical đang ${JSON.stringify(co)}`);\nconst cuoi = fs.readFileSync('quan-sat/canh-bao.log', 'utf8').trim().split('\\n').slice(-2);\nd += ok(cuoi.length === 2 &amp;&amp; cuoi.every((x) =&gt; !x.includes('ALERT')), `hai lần đo gần nhất không còn cảnh báo: ${cuoi.map((x) =&gt; x.slice(11, 19)).join(', ')}`);\nconsole.log(`\\n${d}/8 mục  (lần 500 đầu tiên trong access log: ${dau500}; nhật ký cờ: ${lucCo})`);";
export const L_DIEU_TRA = "#!/bin/bash\n# dieu-tra.sh — lời giải lab 10.5: từ cảnh báo tới nguyên nhân, chỉ bằng log + số đo. Chạy ở thư mục lab khi \"production\" đang chạy.\ncd \"$(dirname \"$0\")/..\"\nhien() { echo \"\\$ $*\"; }\necho '# ===== 1. Cảnh báo nói gì, bắt đầu từ lúc nào? ====='\nhien 'grep -m1 -B1 ALERT quan-sat/canh-bao.log'\ngrep -m1 -B1 ALERT quan-sat/canh-bao.log\necho '# ===== 2. Cái gì vừa thay đổi? (deploy VÀ cờ VÀ cấu hình) ====='\nhien 'cat cau-hinh/nhat-ky-thay-doi.log cau-hinh/nhat-ky-co.log'\ncat cau-hinh/nhat-ky-thay-doi.log cau-hinh/nhat-ky-co.log\nCO=$(grep -o '^[^ ]*' cau-hinh/nhat-ky-co.log | head -1)\necho '# ===== 3. Phạm vi: route nào lỗi, route nào chậm — đo ở nginx, sau lúc đổi cờ ====='\nhien \"jq -s -r --arg t \\\"\\$CO\\\" '[.[] | select(.t &gt; \\$t and .uri != \\\"/metrics\\\")] | group_by(.uri)[] | (map(.rt)|sort) as \\$r | \\\"\\\\(.[0].uri)  \\\\(length) req  5xx \\\\(map(select(.status&gt;=500))|length)  p50 \\\\(\\$r[length/2|floor]*1000|floor) ms  p95 \\\\(\\$r[length*0.95|floor]*1000|floor) ms\\\"' quan-sat/nginx-access.log\"\njq -s -r --arg t \"${CO%.*}\" '[.[] | select(.t &gt; $t and .uri != \"/metrics\")] | group_by(.uri)[] | (map(.rt)|sort) as $r | \"\\(.[0].uri)  \\(length) req  5xx \\(map(select(.status&gt;=500))|length)  p50 \\($r[length/2|floor]*1000|floor) ms  p95 \\($r[length*0.95|floor]*1000|floor) ms\"' quan-sat/nginx-access.log\nhien \"jq -s -r --arg t \\\"\\$CO\\\" '[.[] | select(.t &lt; \\$t and .uri != \\\"/metrics\\\")] | (map(.rt)|sort) as \\$r | \\\"TRƯỚC lúc đổi cờ: \\\\(length) req  5xx \\\\(map(select(.status&gt;=500))|length)  p95 \\\\(\\$r[length*0.95|floor]*1000|floor) ms\\\"' quan-sat/nginx-access.log\"\njq -s -r --arg t \"${CO%.*}\" '[.[] | select(.t &lt; $t and .uri != \"/metrics\")] | (map(.rt)|sort) as $r | \"TRƯỚC lúc đổi cờ: \\(length) req  5xx \\(map(select(.status&gt;=500))|length)  p95 \\($r[length*0.95|floor]*1000|floor) ms\"' quan-sat/nginx-access.log\necho '# ===== 4. Lỗi 500 là lỗi gì? Gom theo thông báo + dòng mã ====='\nhien \"docker compose logs --no-color api-a api-b | grep -o '{.*\\\"lỗi chưa bắt\\\".*' | jq -s -c 'group_by(.loi)[] | {loi: .[0].loi, lan: length, so_sv: (map(.sv)|unique|length), tai: .[0].stack[1]}'\"\ndocker compose logs --no-color api-a api-b | grep -o '{.*\"lỗi chưa bắt\".*' | jq -s -c 'group_by(.loi)[] | {loi: .[0].loi, lan: length, so_sv: (map(.sv)|unique|length), tai: .[0].stack[1]}'\necho '# ===== 5. Người gặp 500 có phải đúng nhóm được bật cờ? ====='\nhien 'node dap-an/nhom-co.mjs'\ndocker compose logs --no-color api-a api-b | grep -o '{.*\"lỗi chưa bắt\".*' | jq -r .sv | sort -u &gt; /tmp/dbg-lab10-sv500.txt\nnode dap-an/nhom-co.mjs /tmp/dbg-lab10-sv500.txt\necho '# ===== 6. Chậm ở đâu? So ba nguồn số đo của cùng một máy ====='\nM=$(ls quan-sat/metrics/*-api-a.prom | tail -1)\nhien \"grep -E 'eventloop|duration_ms_(bucket.*le=\\\"250\\\"|count)' \\$(ls quan-sat/metrics/*-api-a.prom | tail -1) | grep -E 'eventloop|/phong'\"\ngrep -E 'eventloop|duration_ms_(bucket.*le=\"250\"|count)' \"$M\" | grep -E 'eventloop|/phong'\nhien \"jq -s -r --arg t \\\"\\$CO\\\" '[.[] | select(.t &gt; \\$t and .uri == \\\"/phong\\\")] | \\\"nginx thấy /phong quá 250 ms: \\\\(map(select(.rt &gt; 0.25))|length)/\\\\(length)\\\"' quan-sat/nginx-access.log\"\njq -s -r --arg t \"${CO%.*}\" '[.[] | select(.t &gt; $t and .uri == \"/phong\")] | \"nginx thấy /phong quá 250 ms: \\(map(select(.rt &gt; 0.25))|length)/\\(length)\"' quan-sat/nginx-access.log\necho '# ===== 7. Một request vô can bị chậm — lấy làm bằng chứng ====='\nhien \"jq -c --arg t \\\"\\$CO\\\" 'select(.t &gt; \\$t and .uri == \\\"/phong\\\" and .rt &gt; 0.25)' quan-sat/nginx-access.log | head -2\"\njq -c --arg t \"${CO%.*}\" 'select(.t &gt; $t and .uri == \"/phong\" and .rt &gt; 0.25)' quan-sat/nginx-access.log | head -2";
export const L_NHOM_CO = "// nhom-co.mjs &lt;tệp danh sách sv gặp 500&gt; — dùng ĐÚNG hàm chia nhóm của app để kiểm: người gặp lỗi có nằm trong 25% được bật cờ không.\nimport fs from 'node:fs';\nimport { o } from '../app/co.mjs';\nimport { SV, lichCua } from '../app/du-lieu.mjs';\nconst gap = fs.readFileSync(process.argv[2], 'utf8').split('\\n').filter(Boolean);\nconst trongNhom = (sv) =&gt; o('xuat-ical', sv) &lt; 25;\nconst nhom = SV.filter(trongNhom);\nconsole.log(`sinh viên gặp 500: ${gap.length}; nằm trong nhóm 25% của cờ xuat-ical: ${gap.filter(trongNhom).length}/${gap.length}`);\nconsole.log(`nhóm 25%: ${nhom.length}/${SV.length} sinh viên; trong nhóm, người có lượt đặt phong = null: ${nhom.filter((s) =&gt; lichCua(s).some((d) =&gt; !d.phong)).length}`);";
export const L_CAM_MAU = "#!/bin/bash\n# cam-mau.sh — cầm máu bằng công tắc ngắt (không deploy, không restart), ghi nhật ký cờ, rồi chờ hai lượt đo.\ncd \"$(dirname \"$0\")/..\"\nhien() { echo \"\\$ $*\"; }\nhien \"jq '.\\\"xuat-ical\\\".tat = true' cau-hinh/flags.json &gt; /tmp/f &amp;&amp; cat /tmp/f &gt; cau-hinh/flags.json\"\njq '.\"xuat-ical\".tat = true' cau-hinh/flags.json &gt; /tmp/dbg-lab10-f &amp;&amp; cat /tmp/dbg-lab10-f &gt; cau-hinh/flags.json\nhien 'echo \"$(date -u +%FT%TZ) xuat-ical tat=true  (người trực: cuong, sự cố LAB-1050)\" &gt;&gt; cau-hinh/nhat-ky-co.log'\necho \"$(date -u +%FT%TZ) xuat-ical tat=true  (người trực: cuong, sự cố LAB-1050)\" &gt;&gt; cau-hinh/nhat-ky-co.log\nsleep 16\nhien 'tail -n 4 quan-sat/canh-bao.log'\ntail -n 4 quan-sat/canh-bao.log";
export const L_DIFF = "--- ../app/api.mjs\t2026-11-24 08:28:19.262029415 +0700\n+++ app-sua/api.mjs\t2026-11-24 08:28:10.854371967 +0700\n@@ -1,11 +1,11 @@\n // api.mjs — LabFlow API 2.5.0 (\"production\" của lab 10.5). Chạy KHÔNG có --inspect: không attach được, chỉ có log + /metrics.\n import http from 'node:http';\n-import { pbkdf2Sync, randomUUID } from 'node:crypto';\n+import { createHash, randomUUID } from 'node:crypto';\n import { monitorEventLoopDelay } from 'node:perf_hooks';\n import { bat } from './co.mjs';\n import { lichCua } from './du-lieu.mjs';\n \n-const VER = '2.5.0', MAY = process.env.HOSTNAME;\n+const VER = '2.5.1', MAY = process.env.HOSTNAME;\n const log = (o) =&gt; process.stdout.write(JSON.stringify({ t: new Date().toISOString(), ver: VER, may: MAY, ...o }) + '\\n');\n \n // ---- số đo kiểu Prometheus, tự viết cho gọn (thực tế: prom-client) ----\n@@ -35,9 +35,10 @@\n function icalMoi(sv) {\n   const ds = lichCua(sv);\n   const ev = ds.map((d) =&gt; {\n-    // UID ổn định cho mỗi sự kiện (để Google Calendar không nhân đôi khi tải lại)\n-    const uid = pbkdf2Sync(String(d.id), 'labflow', 200000, 16, 'sha256').toString('hex');\n-    return `BEGIN:VEVENT\\nUID:${uid}@labflow\\nDTSTART;VALUE=DATE:${d.ngay.replaceAll('-', '')}\\nSUMMARY:Đặt ${d.phong.ten}\\nEND:VEVENT`;\n+    // UID chỉ cần ổn định và không trùng — không cần là hàm băm mật khẩu (pbkdf2 cố tình chậm, và bản Sync chặn event loop)\n+    const uid = createHash('sha256').update(`lich:${d.id}`).digest('hex').slice(0, 32);\n+    const ten = d.phong ? d.phong.ten : 'phòng chưa xếp';         // đặt online trước: phong = null là dữ liệu HỢP LỆ\n+    return `BEGIN:VEVENT\\nUID:${uid}@labflow\\nDTSTART;VALUE=DATE:${d.ngay.replaceAll('-', '')}\\nSUMMARY:Đặt ${ten}\\nEND:VEVENT`;\n   });\n   return `BEGIN:VCALENDAR\\nVERSION:2.0\\n${ev.join('\\n')}\\nEND:VCALENDAR\\n`;\n }";
export const L_TRA_LOI = "{\n  \"bat_dau\": \"2026-11-24T01:26:59+00:00\",\n  \"co\": \"xuat-ical\",\n  \"rid_500\": \"14230f35\",\n  \"rid_cham\": \"453fc93e\",\n  \"nguyen_nhan_500\": \"icalMoi() đọc d.phong.ten, nhưng lượt đặt online chưa xếp phòng có phong = null (api.mjs:40) — chỉ người trong nhóm 25% của cờ mới chạy nhánh này\",\n  \"nguyen_nhan_cham\": \"UID mỗi sự kiện tính bằng pbkdf2Sync 200.000 vòng — đồng bộ, chặn event loop ~40 ms mỗi sự kiện, mọi request khác trên cùng máy phải xếp hàng (event loop lag p99 184 ms); histogram của app không thấy vì thời gian chờ nằm ngoài handler\",\n  \"cam_mau\": \"tắt cờ xuat-ical (tat=true) lúc 01:30:57Z — không deploy, không restart\",\n  \"de_xuat_sua\": \"UID bằng sha256 thường; xử lý phong = null; test cho lượt chưa xếp phòng; đo độ trễ ở rìa; tăng cờ theo bậc 1% → 5% → 25% có theo dõi\"\n}";
